"""Offline portable chapter-player, plus a proxy at the film's native pixel-grid resolution."""
from pathlib import Path
import subprocess,base64,html
root=Path(__file__).resolve().parents[1];name='Bobo_Max_Episode_001_Dont_Look_Behind_You.mp4';video=root/'renders'/name
proxy=root/'renders/Pixel_Horror_Preview.mp4'
if not proxy.exists() or proxy.stat().st_mtime<video.stat().st_mtime:
 subprocess.run(['ffmpeg','-y','-v','error','-i',str(video),'-vf','scale=360:640:flags=neighbor,format=yuv420p','-c:v','libx264','-preset','medium','-crf','22','-color_range','tv','-colorspace','bt709','-c:a','aac','-b:a','128k','-movflags','+faststart',str(proxy)],check=True)
encoded=base64.b64encode(proxy.read_bytes()).decode();poster=base64.b64encode((root/'public/pixel/stills/peak-fear.png').read_bytes()).decode()
chapters=[(0,'The message'),(12,'The sound'),(30,'Max calls'),(46,'The reveal'),(58,'The prank'),(68,'Bravest guy alive')]
buttons=''.join(f'<button data-time="{t}"><small>{i+1:02d} / {t:02d}s</small>{html.escape(s)}</button>' for i,(t,s) in enumerate(chapters))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bobo & Max — Don't Look Behind You</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#e1e5ed;font:15px Arial,sans-serif}main{max-width:1050px;margin:auto;padding:30px 24px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #323a55;padding-bottom:20px}header strong{font-size:23px}header span{color:#9ba4c0;font-size:10px;letter-spacing:3px}.layout{display:grid;grid-template-columns:360px 1fr;gap:55px;align-items:center;margin-top:35px}video{display:block;width:360px;max-width:100%;aspect-ratio:9/16;image-rendering:pixelated;background:#020613;box-shadow:0 25px 80px #0008;border:1px solid #4c5571}h1{font-size:49px;line-height:1.03;letter-spacing:-2px;margin:20px 0}h1 span{color:#d4b7c9}.eyebrow{color:#a9a1cf;letter-spacing:4px;font-size:10px}p{line-height:1.8;color:#9eacc5}.chapters{display:grid;gap:8px;margin-top:28px}button{padding:12px 15px;border:1px solid #3a4560;background:#19233a;color:#dde3f0;display:flex;gap:20px;align-items:center;font:inherit;font-size:12px;text-align:left;cursor:pointer}button:hover,button:focus-visible{background:#33415b}small{font-size:9px;letter-spacing:1px;color:#a6a1ba}.note{font-size:10px}.clock{color:#dbbfd0;font-size:12px;margin-top:20px;font-variant-numeric:tabular-nums}@media(max-width:720px){.layout{grid-template-columns:1fr;gap:35px}video{margin:auto}h1{font-size:40px}header span{display:none}main{padding:20px 16px}}</style><main><header><strong>BOBO & MAX / AFTER DARK</strong><span>EPISODE 001</span></header><div class="layout"><video id="film" controls playsinline preload="metadata" poster="data:image/png;base64,POSTER" src="data:video/mp4;base64,VIDEO"></video><section><div class="eyebrow">03:03 AM. ONE NEW MESSAGE.</div><h1>Don’t look<br/><span>behind you.</span></h1><p>An unknown number.<br/>A very bad friend.<br/>The scariest thing in the room has a dust compartment.</p><div class="chapters">CHAPTERS</div><div id="clock" class="clock">00:00 / 01:15</div><p class="note">Original pixel artwork, fictional voices, music and sound effects.<br/>Press Play to enable sound. This self-contained file works offline.<br/>Native 360 × 640 preview; the final MP4 is 1080 × 1920.</p></section></div></main><script>const v=document.getElementById('film');document.querySelectorAll('button').forEach(b=>b.onclick=()=>{v.currentTime=Number(b.dataset.time);v.play();});v.ontimeupdate=()=>{const t=Math.floor(v.currentTime);document.getElementById('clock').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')+' / 01:15';};</script></html>'''.replace('POSTER',poster).replace('VIDEO',encoded).replace('CHAPTERS',buttons)
preview=root/'renders/Pixel_Horror_Preview.html';preview.write_text(page)
for p in [video,proxy,preview]:p.chmod(0o644);print(p.name,p.stat().st_size)
